  '{properties,shared,properties,skills,properties,hawk}',
  $j${"description":"Kit: Hawk Companion","default":{},"type":"object","properties":{"max":{"default":7,"description":"Max level","type":"number","minimum":1,"maximum":20},"dmg":{"description":"Dive damage","default":{},"type":"object","properties":{"base":{"default":34,"description":"Value before levels","type":"number","minimum":-1000000,"maximum":1000000},"perLv":{"default":16,"description":"Added per skill level","type":"number","minimum":-10000,"maximum":10000},"min":{"description":"Lower limit","type":"number","minimum":-1000000,"maximum":1000000},"max":{"description":"Upper limit","type":"number","minimum":-1000000,"maximum":1000000}}},"cd":{"description":"Cooldown (s)","default":{},"type":"object","properties":{"base":{"default":2.2,"description":"Value before levels","type":"number","minimum":-1000000,"maximum":1000000},"perLv":{"default":-0.14,"description":"Added per skill level","type":"number","minimum":-10000,"maximum":10000},"min":{"default":0.9,"description":"Lower limit","type":"number","minimum":-1000000,"maximum":1000000},"max":{"description":"Upper limit","type":"number","minimum":-1000000,"maximum":1000000}}},"range":{"default":230,"description":"Hunting range","type":"number","minimum":0,"maximum":2300},"flight":{"default":0.35,"description":"Dive time (s)","type":"number","minimum":0,"maximum":600},"kb":{"default":40,"description":"Knockback","type":"number","minimum":0,"maximum":400},"r":{"default":0,"description":"Dive splash radius: monsters this close to the prey are hit too (0 = prey only)","type":"number","minimum":0,"maximum":200},"guardN":{"default":0,"description":"Monsters this close to Kit that make the Hawk defend: it dives the nearest one instead of the biggest (0 = never)","type":"number","minimum":0,"maximum":50},"guardR":{"default":40,"description":"Hawk defend radius around Kit","type":"number","minimum":0,"maximum":400},"gustKb":{"default":0,"description":"Hawk Gust: when the Hawk defends, monsters around Kit are pushed back this hard (0 = no gust)","type":"number","minimum":0,"maximum":10},"gustStun":{"default":0,"description":"Hawk Gust: monsters it pushes are stunned (s); bosses never","type":"number","minimum":0,"maximum":600},"gustR":{"default":42,"description":"Hawk Gust radius around Kit","type":"number","minimum":0,"maximum":420},"gustCd":{"default":3,"description":"Hawk Gust: at most one gust every (s), however often the Hawk defends","type":"number","minimum":0,"maximum":600},"stunBase":{"default":0,"description":"Every Hawk dive stuns the non-boss monsters it strikes (s); the evolved Hawk uses its own stun","type":"number","minimum":0,"maximum":600},"nearCh":{"default":0,"description":"Through this Chapter the Hawk dives the nearest monster instead of the biggest (0 = never)","type":"number","minimum":0,"maximum":20},"evo":{"description":"Changes applied when the skill evolves","default":{},"type":"object","properties":{"n":{"default":2,"description":"Hawks","type":"number","minimum":1,"maximum":4},"stun":{"default":0.8,"description":"Stun (s); bosses are slowed","type":"number","minimum":0,"maximum":600}}},"awk":{"description":"Stormhunter (Awakened, awaken.form 1): Hawk Flock; Arrow Rain turns to fire arrows on its prey","default":{},"type":"object","properties":{"n":{"default":5,"description":"Hawks in the flock","type":"number","minimum":1,"maximum":12},"dmgMul":{"default":0.6,"description":"Damage × per hawk","type":"number","minimum":0,"maximum":10},"r":{"default":16,"description":"Splash radius of each dive","type":"number","minimum":0,"maximum":160},"galePull":{"default":40,"description":"Gale Step blades pull monsters toward them (Gathered)","type":"number","minimum":0,"maximum":400},"shockMul":{"default":1.5,"description":"Thunder Hawk damage × on Shocked monsters","type":"number","minimum":0,"maximum":10},"shockJump":{"default":1.6,"description":"Thunder Hawk jump range × toward Shocked monsters","type":"number","minimum":0,"maximum":10}}}}}$j$::jsonb)
